if json.Unmarshal(raw, &links) != nil || links.Pages.Next == "" {
	return ""
}
u, err := url.Parse(links.Pages.Next)

if err != nil {
	return ""
}
p := strings.TrimPrefix(u.Path, "/v2/")
p = strings.TrimPrefix(p, "/")
if u.RawQuery != "" {
	return p + "?" + u.RawQuery
}

